insert into student(
    name, no, gender, phone, id_card, is_boarding, address, grade_level, enrollment_date,
    clazz_id, violation_count, violation_score, create_time, update_time
)
values(
    #{name}, #{no}, #{gender}, #{phone}, #{idCard}, #{isBoarding}, #{address}, #{gradeLevel},
    #{enrollmentDate}, #{clazzId}, #{violationCount}, #{violationScore}, #{createTime}, #{updateTime}
)

mapper.update:
update student
name = #{name}, no = #{no}, gender = #{gender}, phone = #{phone}, id_card = #{idCard}, is_boarding = #{isBoarding}, address = #{address}, grade_level = #{gradeLevel}, enrollment_date = #{enrollmentDate}, clazz_id = #{clazzId}, violation_count = #{violationCount}, violation_score = #{violationScore}, update_time = #{updateTime},
where id = #{id}

mapper.select:
select s.id, s.name, s.no, s.gender, s.phone, s.id_card as idCard, s.is_boarding as isBoarding, s.address, s.grade_level as gradeLevel, s.enrollment_date as enrollmentDate, s.clazz_id as clazzId, s.violation_count as violationCount, s.violation_score as violationScore, s.create_time as createTime, s.update_time as updateTime, c.name as clazzName from student s left join clazz c on s.clazz_id = c.id
and s.name like concat('%', #{name}, '%')
and s.grade_level = #{gradeLevel}
and s.clazz_id = #{clazzId}
order by s.update_time desc, s.id desc
